/** Everything the markup binds to, for one position in the loop. */
export function values(p) {
  // p is the argument.
  function lin(k) {
    if (p <= k[0][0]) return k[0][1];
    for (var i = 1; i < k.length; i++) if (p <= k[i][0]) { var a = k[i-1], b = k[i], f = (p - a[0]) / (b[0] - a[0]); f = 1 - Math.pow(1 - f, 3); return a[1] + (b[1] - a[1]) * f; }
    return k[k.length-1][1];
  }
  var BEST = 1;
  var out = p < 94 ? 1 : Math.max(0, 1 - (p - 94) / 6);
  var ph = [[0,12],[12,24],[24,40],[40,66],[66,80]];
  var v = {};
  for (var i = 0; i < 5; i++) { v['on'+i] = (p >= ph[i][0] && p < ph[i][1]) ? 1 : 0; v['done'+i] = (p >= ph[i][1] && p < 97) ? out : 0; }
  v.reqO = lin([[0,0],[2,1],[10,1],[12,0]]); v.reqT = 'translateY(' + lin([[0,16],[2,0]]).toFixed(1) + 'px)';
  v.zoneO = lin([[12,0],[16,1],[24,1],[28,0]]) * out;
  // which option is on the plan
  var sel;
  if (p < 24) sel = -1; else if (p < 48) sel = 0; else if (p < 56) sel = 1; else if (p < 66) sel = 2; else sel = BEST;
  var fade = function (i) {
    if (sel === -1) return 0;
    if (p < 24) return 0;
    var edges = [[24,48,0],[48,56,1],[56,66,2],[66,200,BEST]];
    var o = 0;
    edges.forEach(function (e) { if (e[2] !== i) return; var s = e[0], t = e[1]; var a = Math.min(1, (p - s) / 1.5), b = Math.min(1, (t - p) / 1.5); if (p >= s && p < t) o = Math.max(o, Math.min(a, b > 0 ? 1 : 0)); });
    return o;
  };
  for (var i = 0; i < 3; i++) v['op'+i] = fade(i) * out;
  var pdf = lin([[24,0],[34,1]]);
  v.pd = 'stroke-dasharray: 1; stroke-dashoffset: ' + (p < 40 ? (1 - pdf).toFixed(3) : '0') + ';';
  v.tg = (p < 40 ? lin([[33,0],[38,1]]) : 1);
  v.fillO = 1;
  // compare panel
  v.cmpO = lin([[38,0],[41,1]]) * out;
  var shown = [p >= 41 ? 1 : 0, p >= 48 ? 1 : 0, p >= 56 ? 1 : 0];
  for (var i = 0; i < 3; i++) { v['row'+i] = (p >= 38 && p < 97) ? (shown[i] ? 1 : 0.25) * out : 0; v['cur'+i] = (sel === i && p >= 40 && p < 66) ? out : 0; }
  v.best = (p >= 66 && p < 97) ? out : 0;
  v.optA = (sel === 0 && p >= 24 && p < 97) ? out : 0; v.optB = (sel === 1 && p >= 24 && p < 97) ? out : 0; v.optC = (sel === 2 && p >= 24 && p < 97) ? out : 0;
  v.optChip = (p >= 24 && p < 97) ? out : 0;
  v.legO = lin([[26,0],[32,1]]) * out;
  return { v: v };}

